using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides web search capabilities to the research agent.
/// Uses a simple HTTP-based approach to fetch and extract text from web pages.
/// </summary>
public sealed class WebSearchTool
{
    private readonly HttpClient _httpClient;

    public WebSearchTool(HttpClient httpClient)
    {
        _httpClient = httpClient;
        _httpClient.DefaultRequestHeaders.UserAgent.ParseAdd(
            "ResearchAgent/1.0 (compatible; research-bot)");
    }

    [Description("Search the web for information on a given query. Returns a list of search result snippets.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query to look up")] string query,
        [Description("Maximum number of results to return (default 5)")] int maxResults = 5,
        CancellationToken cancellationToken = default)
    {
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";
            var html = await _httpClient.GetStringAsync(url, cancellationToken);

            var results = ParseSearchResults(html, maxResults);

            if (results.Count == 0)
            {
                return $"No results found for: {query}";
            }

            return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
        }
        catch (HttpRequestException ex)
        {
            return $"Search failed: {ex.Message}. Try a different query or check connectivity.";
        }
    }

    [Description("Fetch the text content of a specific web page URL.")]
    public async Task<string> FetchPageAsync(
        [Description("The full URL of the web page to fetch")] string url,
        [Description("Maximum characters of content to return (default 3000)")] int maxLength = 3000,
        CancellationToken cancellationToken = default)
    {
        try
        {
            var html = await _httpClient.GetStringAsync(url, cancellationToken);
            var text = ExtractTextFromHtml(html);

            if (text.Length > maxLength)
            {
                text = text[..maxLength] + "\n... [content truncated]";
            }

            return string.IsNullOrWhiteSpace(text)
                ? "Could not extract meaningful content from this page."
                : text;
        }
        catch (HttpRequestException ex)
        {
            return $"Failed to fetch page: {ex.Message}";
        }
    }

    private static List<SearchResult> ParseSearchResults(string html, int maxResults)
    {
        var results = new List<SearchResult>();
        var snippetMarker = "result__snippet";
        var titleMarker = "result__a";

        var position = 0;
        while (results.Count < maxResults && position < html.Length)
        {
            var titleIdx = html.IndexOf(titleMarker, position, StringComparison.Ordinal);
            if (titleIdx < 0)
            {
                break;
            }

            var title = ExtractTagContent(html, titleIdx);
            var snippetIdx = html.IndexOf(snippetMarker, titleIdx, StringComparison.Ordinal);
            var snippet = snippetIdx >= 0 ? ExtractTagContent(html, snippetIdx) : "";

            var href = ExtractHref(html, titleIdx);

            if (!string.IsNullOrWhiteSpace(title))
            {
                results.Add(new SearchResult(
                    CleanHtmlText(title),
                    CleanHtmlText(snippet),
                    href ?? ""));
            }

            position = snippetIdx >= 0 ? snippetIdx + 1 : titleIdx + 1;
        }

        return results;
    }

    private static string? ExtractHref(string html, int startFrom)
    {
        var hrefIdx = html.LastIndexOf("href=\"", startFrom, Math.Min(startFrom, 500), StringComparison.Ordinal);
        if (hrefIdx < 0)
        {
            hrefIdx = html.IndexOf("href=\"", startFrom, StringComparison.Ordinal);
        }
        if (hrefIdx < 0) return null;

        var urlStart = hrefIdx + 6;
        var urlEnd = html.IndexOf('"', urlStart);
        if (urlEnd < 0) return null;

        var rawUrl = html[urlStart..urlEnd];
        // DuckDuckGo wraps URLs in a redirect
        if (rawUrl.Contains("uddg=", StringComparison.Ordinal))
        {
            var uddgIdx = rawUrl.IndexOf("uddg=", StringComparison.Ordinal) + 5;
            var ampIdx = rawUrl.IndexOf('&', uddgIdx);
            rawUrl = ampIdx > 0 ? rawUrl[uddgIdx..ampIdx] : rawUrl[uddgIdx..];
            rawUrl = Uri.UnescapeDataString(rawUrl);
        }

        return rawUrl;
    }

    private static string ExtractTagContent(string html, int markerPosition)
    {
        var tagEnd = html.IndexOf('>', markerPosition);
        if (tagEnd < 0) return "";

        var contentStart = tagEnd + 1;
        var contentEnd = html.IndexOf('<', contentStart);
        if (contentEnd < 0) return "";

        var content = html[contentStart..contentEnd];
        var nextClose = html.IndexOf("</", contentEnd, StringComparison.Ordinal);
        if (content.Length < 10 && nextClose > 0)
        {
            content = html[contentStart..nextClose];
        }

        return content;
    }

    private static string ExtractTextFromHtml(string html)
    {
        // Remove script and style blocks
        html = System.Text.RegularExpressions.Regex.Replace(
            html, @"<(script|style)[^>]*>[\s\S]*?</\1>", "",
            System.Text.RegularExpressions.RegexOptions.IgnoreCase);

        // Remove tags
        var text = System.Text.RegularExpressions.Regex.Replace(html, @"<[^>]+>", " ");

        return CleanHtmlText(text);
    }

    private static string CleanHtmlText(string text)
    {
        text = System.Net.WebUtility.HtmlDecode(text);
        text = System.Text.RegularExpressions.Regex.Replace(text, @"\s+", " ");
        return text.Trim();
    }

    private sealed record SearchResult(string Title, string Snippet, string Url);
}

