using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using OpenAI;
using ResearchAgent.Tools;

var builder = Host.CreateApplicationBuilder(args);

// Configure logging — suppress noisy HTTP logs
builder.Logging.SetMinimumLevel(LogLevel.Warning);

// Resolve API key and model from config or environment
var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the API key via 'AI:ApiKey' in appsettings.json, user-secrets, or the OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:Model"]
    ?? Environment.GetEnvironmentVariable("OPENAI_MODEL")
    ?? "gpt-4o-mini-2024-07-18";

// Register the chat client via MEAI abstraction
builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

builder.Services.AddSingleton<HttpClient>();

var host = builder.Build();

// Build tool instances
var httpClient = host.Services.GetRequiredService<HttpClient>();
var webSearch = new WebSearchTool(httpClient);
var notes = new NoteTool();

// Create AI functions from tool instances
var tools = new AIFunctionFactory.AIFunctionCollection
{
    AIFunctionFactory.Create(webSearch.SearchWebAsync),
    AIFunctionFactory.Create(webSearch.FetchPageAsync),
    AIFunctionFactory.Create(notes.SaveNote),
    AIFunctionFactory.Create(notes.GetNotes),
    AIFunctionFactory.Create(notes.GetNoteSummary),
};

// Create the agent with tools
var chatClient = host.Services.GetRequiredService<IChatClient>();
var agent = new ChatClientAgent(chatClient, tools)
{
    Name = "ResearchAgent",
    Description = "An AI research agent that searches the web and takes structured notes to produce a research summary.",
    Instructions = """
        You are a thorough research agent. When given a topic:

        1. **Search** — Use SearchWebAsync to find relevant information. Run multiple searches
           with different query angles to get comprehensive coverage.
        2. **Read** — Use FetchPageAsync to read promising pages from the search results for deeper detail.
        3. **Take notes** — Use SaveNote to record each key finding with an appropriate topic tag
           and the source URL. Organize notes by subtopics (e.g., 'definition', 'history',
           'current-status', 'key-finding', 'statistic').
        4. **Review** — Use GetNotes to review all your collected notes.
        5. **Summarize** — Produce a well-structured research summary with sections, citing your
           sources. Include a "Sources" section at the end.

        Be methodical: search, read, note, then summarize. Do not skip the note-taking step.
        """,
};

// Prompt the user for a topic
Console.ForegroundColor = ConsoleColor.Cyan;
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║       🔍 AI Research Agent               ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.ResetColor();
Console.WriteLine();
Console.Write("Enter a research topic (or press Enter for default): ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrWhiteSpace(topic))
{
    topic = "the current state of quantum computing in 2025";
}

Console.WriteLine();
Console.ForegroundColor = ConsoleColor.Yellow;
Console.WriteLine($"Researching: {topic}");
Console.WriteLine("This may take a minute as the agent searches, reads, and takes notes...");
Console.ResetColor();
Console.WriteLine();

// Run the agent
var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and produce a comprehensive summary: {topic}"),
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 15,
};

string? finalResponse = null;
await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
        finalResponse = (finalResponse ?? "") + message.Text;
    }
}

Console.WriteLine();
Console.WriteLine();

// Show note statistics
Console.ForegroundColor = ConsoleColor.Green;
Console.WriteLine("── Notes collected during research ──");
Console.ResetColor();
Console.WriteLine(notes.GetNoteSummary());

